def start_to_start(parent, child) -> int:
    return child.parent_lag                         # child starts >= parent starts + lag


def finish_to_start(parent, child) -> int:
    return parent.duration + child.parent_lag       # child starts >= parent finishes + lag

def max_lag_rows(plan, k: int):
    """If the child is funded, it has started by year t whenever the parent had started by t - k."""
    for t in small.years:
        plan.model.add_linear_constraint(
            plan.started_by(CHILD, t) >= plan.started_by(PARENT, t - k) + plan.started(CHILD) - 1,
            name=f"within_{CHILD}_{t}")

def usable_years(parent_starts, child_starts, low: int, high: int | None) -> tuple[list[int], list[int]]:
    """Start years of each project that some start year of the other can pair with."""
    def fits(s, t):
        return t - s >= low and (high is None or t - s <= high)
    child = [t for t in child_starts if any(fits(s, t) for s in parent_starts)]
    parent = [s for s in parent_starts if any(fits(s, t) for t in child_starts)]
    return parent, child
